                   : _punchIdleState_T_1 & acceptPunch))),
    .W0_clk  (clock),
    .W0_data
      (_GEN_66
         ? 8'h0
         : _GEN_43
             ? (spiDone ? spiRxByte : 8'h0)
             : _GEN_55
                 ? 8'h0
                 : _io_outValid_T_2
                     ? (_GEN_57 ? 8'h0 : io_punchData)
                     : _GEN_65 ? io_punchData : 8'h0)
  );
  assign io_sdSck = spiSckReg;
  assign io_sdMosi = spiMosiReg;
  assign io_sdCsN = csNReg;
  assign io_outValid = io_outValid_0;
  assign io_outData = userNulTerminator ? 8'h1A : servedByteReg;
  assign io_punchReady = canPunch;
  assign io_initialized = initializedReg;
  assign io_active = state != 6'h1D & ~errorReg;
  assign io_done = doneReg;
  assign io_error = errorReg;
